 const wages=[],actions=[{id:'shift',name:'รับงานเพิ่มหนึ่งช่วง',description:'ได้ค่าจ้างสุทธิ 360–720 ทอง · สุขภาพ −3 ความสุข −2',min:16},{id:'aid',name:'ขอทุนฉุกเฉินจากชุมชน',description:'เฉพาะเงินพร้อมใช้น้อยกว่า 1,000 และมีหนี้ · ไม่เกินปีละครั้ง',min:16},{id:'family',name:'ช่วยเงินครอบครัว 500 ทอง',description:'โอนจริงจากเงินส่วนตัวเข้าเงินครอบครัว',min:16},{id:'repay',name:'ชำระหนี้ 500 ทอง',description:'ลดเงินต้นที่ต้องจ่ายดอกเบี้ย',min:16}];
