 function action(s,id){const e=ensure(s),q=s.calendar?.count??0,a=actions.find(a=>a.id===id);if(!a||typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)&&['shift','aid'].includes(id)||s.dead||!s.accepted||s.outcome||s.calendar?.pending||Engine.biological(s)<a.min||e.actionQuarter===q)return false;let text='';if(id==='shift'){const value=360+hash(s,q+721)%361;s.gold=round(cap(s.gold+value));s.health=cap(s.health-3,0,100);s.joy=cap(s.joy-2,0,100);text='คุณใช้เวลาพักรับงานเพิ่ม ได้ค่าจ้างสุทธิ '+value+' ทอง แต่แรงและเวลาของคนใกล้ตัวลดลง'}if(id==='aid'){if(e.aidYear===s.age||s.gold>=1000||e.debt<=0)return false;const help=Math.min(e.debt,1800);e.debt=round(e.debt-help);e.aidYear=s.age;text='กองทุนชุมชนช่วยชำระยอดจำเป็น '+help+' ทอง เงินช่วยไม่ใช่รายรับประจำ'}if(id==='family'){if(s.gold<500)return false;s.gold=round(s.gold-500);e.familyFund=round(cap(e.familyFund+500));s.bond=cap(s.bond+2,0,100);text='คุณแบ่ง 500 ทองให้ครอบครัว เงินสำรองที่บ้านเพิ่มขึ้นจริง'}if(id==='repay'){if(s.gold<500||e.debt<=0)return false;const amount=Math.min(500,e.debt);s.gold=round(s.gold-amount);e.debt=round(e.debt-amount);text='คุณชำระเงินต้น '+amount+' ทอง ยอดหนี้เหลือ '+e.debt.toLocaleString('en-US')+' ทอง'}e.actionQuarter=q;add(s,a.name,text);return true}
